import{_ as t,o as r,c as a,a5 as o}from"./chunks/framework.bIR-4glx.js";const u=JSON.parse('{"title":"Real Projects, Jobs, and Entrepreneurship | Turn Learning into Evidence","description":"Start with a customer problem, job-search English, or a deliverable and use a two-week experiment to test a project, career opportunity, or business idea.","frontmatter":{"title":"Real Projects, Jobs, and Entrepreneurship | Turn Learning into Evidence","description":"Start with a customer problem, job-search English, or a deliverable and use a two-week experiment to test a project, career opportunity, or business idea.","updated":"2026-10-14T00:00:00.000Z","topic":"real-projects","intent":"project-validation","schema":"Article","socialImage":"/assets/social/projects-en.png","socialImageAlt":"Real projects, jobs, and entrepreneurship sharing image"},"headers":[],"relativePath":"en/topics/real-projects.md","filePath":"en/topics/real-projects.md","lastUpdated":1791936000000}'),n={name:"en/topics/real-projects.md"};function i(s,e,c,l,p,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="real-projects-jobs-and-entrepreneurship-turn-learning-into-evidence" tabindex="-1">Real Projects, Jobs, and Entrepreneurship: Turn Learning into Evidence <a class="header-anchor" href="#real-projects-jobs-and-entrepreneurship-turn-learning-into-evidence" aria-label="Permalink to &quot;Real Projects, Jobs, and Entrepreneurship: Turn Learning into Evidence&quot;">​</a></h1><p>If you are searching for real project ideas, English job-search preparation, or a way to test a business idea, you do not need to finish a giant course first. Choose a specific person, constraint, and deliverable, then let feedback choose the next step.</p><h2 id="who-it-is-for" tabindex="-1">Who It Is For <a class="header-anchor" href="#who-it-is-for" aria-label="Permalink to &quot;Who It Is For&quot;">​</a></h2><ul><li>People who want learning to become a portfolio piece, case study, interview evidence, or first customers.</li><li>People who need English for international teams, customer conversations, or remote applications.</li><li>People willing to test an entrepreneurship hypothesis at low cost and hear a real “no.”</li></ul><h2 id="start-in-three-steps" tabindex="-1">Start in Three Steps <a class="header-anchor" href="#start-in-three-steps" aria-label="Permalink to &quot;Start in Three Steps&quot;">​</a></h2><ol><li>Choose a real problem from the <a href="./../practice">Practice Map: Start with a Problem</a>, then define the user, deliverable, and completion criteria with the <a href="./../templates/artifact-brief">Artifact Brief and Delivery Card</a>.</li><li>For job search, use <a href="./../threads/part-1/8-job-search-english">Job-search English and Remote Work</a> and the <a href="./../templates/interview-evidence">Job-search English Evidence Card</a> to turn a role description into evidence you can show.</li><li>For entrepreneurship, interview people with <a href="./../threads/practice/customer-discovery">From Problems to First Customers</a>, then record the hypothesis, cost, feedback, and stop condition with the <a href="./../templates/startup-experiment">Startup Experiment</a>.</li></ol><h2 id="next-step" tabindex="-1">Next Step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next Step&quot;">​</a></h2><p>After two weeks, do not ask only “Did I learn it?” Check whether a real person used the work, an interview answer became more specific, a customer continued the conversation, and the cost remains acceptable. Put the result into <a href="./../threads/part-3/2-ai-development-and-resource-layer">AI Development and Resource-layer Business</a> or <a href="./../recent-updates">Recent Updates</a> and start the next cycle.</p>',8)])])}const m=t(n,[["render",i]]);export{u as __pageData,m as default};
